package com.aratech.moveis.pcp.lotes.repository;

import static com.aratech.moveis.pcp.lotes.ProducaoDtos.*;
import com.aratech.moveis.security.exception.AuthException;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;
import java.sql.*;
import java.util.*;

@Repository @RequiredArgsConstructor
public class LotesProducaoRepository {
 final JdbcTemplate jdbc; final JsonMapper json;
 public boolean produtoAtivo(long id){return jdbc.queryForObject("SELECT count(*) FROM produto WHERE id=? AND ativo",Long.class,id)==1;}
 public List<Long> lotesDaOrigem(long id){return jdbc.queryForList("SELECT id FROM pcp_lote_producao WHERE ordem_origem_id=?",Long.class,id);}
 public List<Long> origensDoPedido(long id){return jdbc.queryForList("SELECT id FROM pcp_ordem WHERE pedido_id=?",Long.class,id);}
 public long quantidadePlanejada(long id){return jdbc.queryForObject("SELECT COALESCE(sum(quantidade),0) FROM pcp_lote_producao WHERE ordem_origem_id=?",Long.class,id);}
 public String produtoDaOrigem(long id){return jdbc.queryForObject("SELECT produto FROM pcp_ordem WHERE id=?",String.class,id);}
 public List<Setor> setores(){return jdbc.query("SELECT * FROM fabricacao_setor ORDER BY id",(r,n)->new Setor(r.getLong("id"),r.getString("codigo"),r.getString("nome"),r.getString("recurso"),r.getString("caminho"),r.getString("natureza"),r.getBoolean("exige_medidas")));}
 public Variante variante(long id,boolean lock){return unico(jdbc.query("SELECT id,versao,dados FROM fabricacao_variante WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->new Variante(r.getLong(1),r.getLong(2),json.readValue(r.getString(3),FichaVariante.class)),id),"Variante não encontrada.");}
 public List<OpcaoVariante> variantes(String busca){return jdbc.query("SELECT v.id,v.modelo_id,m.nome,v.codigo,v.nome,v.versao FROM fabricacao_variante v JOIN fabricacao_modelo m ON m.id=v.modelo_id WHERE v.ativo AND m.ativo AND (strpos(lower(m.nome||' '||v.codigo||' '||v.nome),lower(?))>0) ORDER BY m.nome,v.nome LIMIT 100",(r,n)->new OpcaoVariante(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getLong(6)),busca);}
 public long salvar(Long id,FichaVariante dto){if(id==null)return jdbc.queryForObject("INSERT INTO fabricacao_variante(modelo_id,codigo,nome,ativo,dados) VALUES (?,?,?,?,?::jsonb) RETURNING id",Long.class,dto.modeloId(),dto.codigo().strip().toUpperCase(Locale.ROOT),dto.nome().strip(),dto.ativo(),json.writeValueAsString(dto));jdbc.update("UPDATE fabricacao_variante SET codigo=?,nome=?,ativo=?,dados=?::jsonb,versao=versao+1 WHERE id=?",dto.codigo().strip().toUpperCase(Locale.ROOT),dto.nome().strip(),dto.ativo(),json.writeValueAsString(dto),id);return id;}
 public List<Origem> origens(String busca){return jdbc.query("SELECT o.id,o.pedido_id,o.produto,o.quantidade,o.quantidade-COALESCE((SELECT sum(l.quantidade) FROM pcp_lote_producao l WHERE l.ordem_origem_id=o.id),0) disponivel,o.status FROM pcp_ordem o WHERE status IN ('PLANEJADA','EM_PRODUCAO') AND strpos(lower(o.produto||' '||o.id),lower(?))>0 ORDER BY o.id DESC LIMIT 100",(r,n)->new Origem(r.getLong(1),(Long)r.getObject(2),r.getString(3),r.getInt(4),r.getInt(5),r.getString(6)),busca);}
 public void validarOrigem(long id,int quantidade){var rs=jdbc.queryForList("SELECT quantidade,status FROM pcp_ordem WHERE id=? FOR UPDATE",id);if(rs.isEmpty())throw new AuthException(404,"Ordem de origem não encontrada.");var o=rs.getFirst();if(!Set.of("PLANEJADA","EM_PRODUCAO").contains(o.get("status")))throw new AuthException(409,"A ordem de origem não está aberta.");Long usado=jdbc.queryForObject("SELECT COALESCE(sum(quantidade),0) FROM pcp_lote_producao WHERE ordem_origem_id=?",Long.class,id);if(usado+quantidade>((Number)o.get("quantidade")).longValue())throw new AuthException(409,"Quantidade excede o saldo da ordem/pedido de origem.");}
 public long criar(NovoLote d,Variante v,Calculo c,String autor){return jdbc.queryForObject("INSERT INTO pcp_lote_producao(variante_id,revisao,ordem_origem_id,quantidade,previsao,observacoes,snapshot,calculo,chave_operacao,autor_nome) VALUES (?,?,?,?,?,?,?::jsonb,?::jsonb,?,?) RETURNING id",Long.class,v.id(),v.versao(),d.ordemOrigemId(),d.quantidade(),d.previsao(),Objects.toString(d.observacoes(),""),json.writeValueAsString(v),json.writeValueAsString(c),d.chaveOperacao(),autor);}
 public void revisar(long id,Variante v,Calculo c){jdbc.update("UPDATE pcp_lote_producao SET revisao=?,snapshot=?::jsonb,calculo=?::jsonb WHERE id=?",v.versao(),json.writeValueAsString(v),json.writeValueAsString(c),id);}
 public record Registro(long id,long revisao,Long origem,int quantidade,java.time.LocalDate previsao,String observacoes,String autor,Variante snapshot,Calculo calculo) {}
 public Registro registro(long id,boolean lock){return unico(jdbc.query("SELECT * FROM pcp_lote_producao WHERE id=?"+(lock?" FOR UPDATE":""),(r,n)->new Registro(r.getLong("id"),r.getLong("revisao"),(Long)r.getObject("ordem_origem_id"),r.getInt("quantidade"),r.getDate("previsao").toLocalDate(),r.getString("observacoes"),r.getString("autor_nome"),json.readValue(r.getString("snapshot"),Variante.class),json.readValue(r.getString("calculo"),Calculo.class)),id),"Lote não encontrado.");}
 public List<Long> ids(int pagina,String busca){return jdbc.queryForList("SELECT id FROM pcp_lote_producao WHERE strpos(lower(snapshot->'dados'->'ficha'->>'nome'),lower(?))>0 OR id::text=? ORDER BY id DESC LIMIT 12 OFFSET ?",Long.class,busca,busca,pagina*12);}
 public long total(String busca){return jdbc.queryForObject("SELECT count(*) FROM pcp_lote_producao WHERE strpos(lower(snapshot->'dados'->'ficha'->>'nome'),lower(?))>0 OR id::text=?",Long.class,busca,busca);}
 public List<Ordem> ordens(long lote){return jdbc.query("SELECT o.*,l.quantidade,l.revisao,l.snapshot,s.nome setor FROM pcp_ordem_setor o JOIN pcp_lote_producao l ON l.id=o.lote_id JOIN fabricacao_setor s ON s.id=o.setor_id WHERE o.lote_id=? ORDER BY o.setor_id",(r,n)->ordem(r),lote);}
 private Ordem ordem(ResultSet r) throws SQLException {var v=json.readValue(r.getString("snapshot"),Variante.class);var g=json.readValue(r.getString("dados"),Grupo.class);long id=r.getLong("id");return new Ordem(id,r.getLong("lote_id"),"LP-"+r.getLong("lote_id"),r.getLong("setor_id"),r.getString("setor"),v.dados().ficha().nome(),v.dados().nome(),r.getInt("quantidade"),r.getLong("revisao"),r.getString("status"),r.getLong("versao"),g.linhas(),jdbc.queryForList("SELECT item_chave FROM pcp_consumo_setor WHERE ordem_id=?",UUID.class,id),r.getTimestamp("liberado_em").toInstant());}
 public Ordem ordem(long id,long setor,boolean lock){return unico(jdbc.query("SELECT o.*,l.quantidade,l.revisao,l.snapshot,s.nome setor FROM pcp_ordem_setor o JOIN pcp_lote_producao l ON l.id=o.lote_id JOIN fabricacao_setor s ON s.id=o.setor_id WHERE o.id=? AND o.setor_id=?"+(lock?" FOR UPDATE OF o":""),(r,n)->ordem(r),id,setor),"Ordem não encontrada neste setor.");}
 public List<Ordem> fila(long setor,int pagina,String busca){return jdbc.query("SELECT o.*,l.quantidade,l.revisao,l.snapshot,s.nome setor FROM pcp_ordem_setor o JOIN pcp_lote_producao l ON l.id=o.lote_id JOIN fabricacao_setor s ON s.id=o.setor_id WHERE o.setor_id=? AND (strpos(lower(l.snapshot->'dados'->'ficha'->>'nome'),lower(?))>0 OR l.id::text=?) ORDER BY CASE o.status WHEN 'EM_ANDAMENTO' THEN 0 WHEN 'LIBERADA' THEN 1 ELSE 2 END,l.previsao,o.id LIMIT 12 OFFSET ?",(r,n)->ordem(r),setor,busca,busca,pagina*12);}
 public long totalFila(long setor,String busca){return jdbc.queryForObject("SELECT count(*) FROM pcp_ordem_setor o JOIN pcp_lote_producao l ON l.id=o.lote_id WHERE o.setor_id=? AND (strpos(lower(l.snapshot->'dados'->'ficha'->>'nome'),lower(?))>0 OR l.id::text=?)",Long.class,setor,busca,busca);}
 public void liberar(long lote,Grupo g){jdbc.update("INSERT INTO pcp_ordem_setor(lote_id,setor_id,dados) VALUES (?,?,?::jsonb) ON CONFLICT(lote_id,setor_id) DO NOTHING",lote,g.setor().id(),json.writeValueAsString(g));}
 public void estado(long id,String status){String campo=status.equals("EM_ANDAMENTO")?"iniciado_em":"concluido_em";jdbc.update("UPDATE pcp_ordem_setor SET status=?,versao=versao+1,"+campo+"=CURRENT_TIMESTAMP WHERE id=?",status,id);}
 public void consumo(long ordem,Linha l,UUID chave){jdbc.update("INSERT INTO pcp_consumo_setor(ordem_id,item_chave,produto_id,quantidade,chave_operacao) VALUES (?,?,?,?,?)",ordem,l.itemChave(),l.produtoEstoqueId(),l.total(),chave);jdbc.update("UPDATE pcp_ordem_setor SET versao=versao+1 WHERE id=?",ordem);}
 private <T>T unico(List<T> dados,String mensagem){if(dados.isEmpty())throw new AuthException(404,mensagem);return dados.getFirst();}
}
